SNAPSHOT_METRICS = {
    "Índice de Basileia": {"tipo_delta": "bps", "escala": "dec"},
    "ROE trim. anualizado": {"tipo_delta": "pp", "escala": "pct"},
    "ROE Ac. Anualizado": {"tipo_delta": "pp", "escala": "pct"},
    "Crédito / Captações": {"tipo_delta": "pp", "escala": "pct"},
    "Desp. Anualizada Captação / Volume Captação": {"tipo_delta": "pp", "escala": "pct"},
    "Desp. Anualizada Captações / Volume Captações": {"tipo_delta": "pp", "escala": "pct"},
    "Perda Esperada / Estágio 3": {"tipo_delta": "pp", "escala": "pct"},
    "Perda Esperada / Carteira": {"tipo_delta": "pp", "escala": "pct"},
    "CET1": {"tipo_delta": "bps", "escala": "dec"},
}


def _snap_metric_delta_meta(metric_cfg: dict) -> tuple[str, str]:
    """Resolve tipo/escala de delta para a métrica da Snapshot."""
    label = metric_cfg.get("label", "")
    meta = SNAPSHOT_METRICS.get(label, {})
    if metric_cfg.get("is_pct", False):
        default_tipo = "bps" if metric_cfg.get("show_bps", False) else "pp"
        default_escala = "pct"
    else:
        default_tipo = "pct"
        default_escala = "pct"
    return (
        metric_cfg.get("delta_kind", meta.get("tipo_delta", default_tipo)),
        metric_cfg.get("scale", meta.get("escala", default_escala)),
    )


def _snap_sparkline_svg(
    values: list,
    width: int = 80,
    height: int = 24,
    color: str = "#1f77b4",
) -> str:
    """Gera SVG inline de sparkline a partir de uma lista de valores numéricos."""
    nums = []
    for v in values:
        try:
            f = float(v)
            if not pd.isna(f):
                nums.append(f)
        except (TypeError, ValueError):
            continue
    if len(nums) < 2:
        return ""
    min_v, max_v = min(nums), max(nums)
    rng = max_v - min_v or 1
    points = []
    for i, v in enumerate(nums):
        x = i / (len(nums) - 1) * width
        y = height - ((v - min_v) / rng * (height - 4) + 2)
        points.append(f"{x:.1f},{y:.1f}")
    polyline = " ".join(points)
    last_x, last_y = points[-1].split(",")
    return (
        f'<svg class="snap-sparkline" width="{width}" height="{height}" '
        f'viewBox="0 0 {width} {height}" style="vertical-align:middle">'
        f'<polyline points="{polyline}" fill="none" stroke="{color}" '
        f'stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>'
        f'<circle cx="{last_x}" cy="{last_y}" r="2" fill="{color}"/>'
        f"</svg>"
    )


def _snap_sparkbars_svg(
    values: list,
    width: int = 80,
    height: int = 24,
    color: str = "#1f77b4",
) -> str:
    """Gera mini barras SVG para cards de rentabilidade/capital."""
    nums = []
    for v in values:
        try:
            f = float(v)
            if not pd.isna(f):
                nums.append(f)
        except (TypeError, ValueError):
            continue
    if len(nums) < 2:
        return ""

    min_v, max_v = min(nums), max(nums)
    rng = max_v - min_v or 1
    bar_gap = 2
    bar_w = max((width - (len(nums) - 1) * bar_gap) / len(nums), 2)
    x = 0.0
    rects = []
    for v in nums:
        h = ((v - min_v) / rng) * (height - 4) + 2
        y = height - h
        rects.append(
            f'<rect x="{x:.1f}" y="{y:.1f}" width="{bar_w:.1f}" height="{h:.1f}" '
            f'rx="1.2" ry="1.2" fill="{color}" opacity="0.72" />'
        )
        x += bar_w + bar_gap
    return (
        f'<svg class="snap-sparkline" width="{width}" height="{height}" '
        f'viewBox="0 0 {width} {height}" style="vertical-align:middle">'
        f'{"".join(rects)}'
        f"</svg>"
    )


def _label_desp_captacao_por_denominador(coluna_denominador: Optional[str]) -> str:
    texto = _normalizar_texto_sem_acento(str(coluna_denominador or ""))
    if "captacao" in texto and "captacoes" not in texto:
        return "Desp. Anualizada Captação / Volume Captação"
    return "Desp. Anualizada Captações / Volume Captações"


def _aliases_metrica_desp_captacao(label_exibicao: Optional[str] = None) -> list[str]:
    aliases = [
        "Desp Captação / Captação",
        "Desp. Anualizada Captação / Volume Captação",
        "Desp. Anualizada Captações / Volume Captações",
    ]
    if label_exibicao:
        aliases = [label_exibicao] + aliases
    # Remove duplicados preservando ordem.
    return list(dict.fromkeys(aliases))


def _snap_delta_calc(
    valor_atual,
    valor_base,
    delta_kind: str = "pct",
    scale: str = "pct",
) -> dict:
    """Calcula texto do delta e metadados para cards/memória da Snapshot."""
    payload = {
        "a": None,
        "b": None,
        "suffix": "—",
        "valido": False,
        "motivo": "período anterior sem dado",
    }
    if valor_atual is None or valor_base is None:
        return payload

    try:
        a, b = float(valor_atual), float(valor_base)
    except (TypeError, ValueError):
        return payload

    if pd.isna(a) or pd.isna(b):
        return payload

    payload["a"] = a
    payload["b"] = b
    if b == 0 and delta_kind == "pct":
        payload["motivo"] = "período anterior igual a zero"
        return payload

    diff = compute_delta(a, b, tipo=delta_kind, escala=scale)
    if diff is None:
        return payload
    if delta_kind == "bps":
        diff_bps = int(round(diff))
        sinal = "+" if diff_bps > 0 else ""
        payload["suffix"] = f"{sinal}{diff_bps} bps"
    elif delta_kind == "pp":
        payload["suffix"] = formatar_numero_br(diff, casas=2, sufixo=" p.p.", com_sinal=True)
    else:
        payload["suffix"] = formatar_numero_br(diff, casas=1, sufixo="%", com_sinal=True)

    payload["valido"] = True
    payload["motivo"] = ""
    return payload


def _snap_delta_html(
    valor_atual,
    valor_base,
    label: str,
    higher_is_better: bool = True,
    delta_kind: str = "pct",
    scale: str = "pct",
) -> str:
    """Gera HTML de um delta (QoQ ou YoY) para o card V2."""
    calc = _snap_delta_calc(valor_atual, valor_base, delta_kind=delta_kind, scale=scale)
    a, b = calc.get("a"), calc.get("b")
    suffix = calc.get("suffix", "—")

    if not calc.get("valido") or a is None or b is None:
        return (
            f'<span class="snap-card__delta snap-card__delta--neutral">'
            f'<span class="snap-card__delta-label">{label}</span> —</span>'
        )

    a_cmp, b_cmp = _snapshot_normalize_cmp_values(a, b, higher_is_better)
    if a_cmp > b_cmp:
        direcao = "up"
    elif a_cmp < b_cmp:
        direcao = "down"
    else:
        direcao = "neutral"

    if direcao == "neutral":
        css_mod = "snap-card__delta--neutral"
        arrow = "—"
    else:
        melhorou = (direcao == "up" and higher_is_better) or (direcao == "down" and not higher_is_better)
        css_mod = "snap-card__delta--positive" if melhorou else "snap-card__delta--negative"
        arrow = "↑" if direcao == "up" else "↓"

    return (
        f'<span class="snap-card__delta {css_mod}">'
        f'{arrow} <span class="snap-card__delta-label">{label}</span> {suffix}</span>'
    )


def _snap_card_status(valor_atual, valor_base, higher_is_better: bool) -> str:
    """Retorna classe CSS para borda esquerda do card hero."""
    if valor_atual is None or valor_base is None:
        return ""
    try:
        a, b = float(valor_atual), float(valor_base)
        if pd.isna(a) or pd.isna(b):
            return ""
        a, b = _snapshot_normalize_cmp_values(a, b, higher_is_better)
    except (TypeError, ValueError):
        return ""
    if a == b:
        return ""
    melhorou = (a > b and higher_is_better) or (a < b and not higher_is_better)
    return "snap-card--improved" if melhorou else "snap-card--worsened"


def _render_snap_card(
    metric_cfg: dict,
    periodo_atual: str,
    periodo_qoq: Optional[str],
    periodo_yoy: Optional[str],
    sparkline_values: Optional[list] = None,
    sparkline_type: str = "line",
    is_hero: bool = False,
) -> str:
    """Monta HTML completo de um card Snapshot V2."""
    serie = metric_cfg.get("serie", {})
    label = metric_cfg.get("label", "Métrica")
    higher_is_better = metric_cfg.get("higher_is_better", True)
    source = metric_cfg.get("source", "")
    comparison = metric_cfg.get("comparison", "qoq")
    delta_kind, delta_scale = _snap_metric_delta_meta(metric_cfg)

    valor_atual = serie.get(periodo_atual)
    valor_fmt = _formatar_valor_snapshot(metric_cfg, valor_atual)

    # Períodos base
    periodo_base_qoq = periodo_qoq
    periodo_base_yoy = periodo_yoy

    valor_qoq = serie.get(periodo_base_qoq) if periodo_base_qoq else None
    valor_yoy = serie.get(periodo_base_yoy) if periodo_base_yoy else None

    # Para métricas YTD, QoQ não faz sentido; comparação principal é YoY
    if comparison == "yoy":
        delta_1 = _snap_delta_html(valor_atual, valor_yoy, "YoY", higher_is_better, delta_kind, delta_scale)
        delta_2 = ""
    else:
        delta_1 = _snap_delta_html(valor_atual, valor_qoq, "QoQ", higher_is_better, delta_kind, delta_scale)
        delta_2 = _snap_delta_html(valor_atual, valor_yoy, "YoY", higher_is_better, delta_kind, delta_scale)

    # Borda esquerda (status) — usa QoQ como base primária
    base_for_status = valor_yoy if comparison == "yoy" else valor_qoq
    status_cls = _snap_card_status(valor_atual, base_for_status, higher_is_better)
    hero_cls = "snap-card--hero" if is_hero else ""

    # Sparkline
    spark_html = ""
    if sparkline_values:
        if sparkline_type == "bars":
            spark_html = _snap_sparkbars_svg(sparkline_values, width=80, height=24)
        else:
            spark_html = _snap_sparkline_svg(sparkline_values, width=80, height=24)

    # Info tooltip
    info_html = ""
    if source:
        safe_source = source.replace('"', '&quot;').replace("'", "&#39;")
        info_html = (
            f'<span class="snap-card__info">i'
            f'<span class="snap-tip">{safe_source}</span></span>'
        )

    return f"""<div class="snap-card {status_cls} {hero_cls}">
  <div class="snap-card__header">
    <span class="snap-card__label">{label}</span>{info_html}
  </div>
  <div class="snap-card__spark-row">
    <span class="snap-card__value">{valor_fmt}</span>
    {spark_html}
  </div>
  <div class="snap-card__comparisons">
    {delta_1}{delta_2}
  </div>
</div>"""


def _render_snap_grid(cards_html: list, grid_class: str) -> str:
    """Wrapa lista de cards HTML em um CSS Grid container."""
    inner = "\n".join(cards_html)
    return f'<div class="snap-grid {grid_class}">{inner}</div>'


