def _garantir_dados_principais(menu_nome: str) -> bool:
    """Garante dados principais apenas quando a aba realmente precisar processar."""
    if 'dados_periodos' in st.session_state and st.session_state['dados_periodos']:
        return True

    with st.status("carregando dados do banco central...", expanded=True) as _status:
        st.write("lendo cache local (parquet)...")
        carregar_dados_periodos()
        ok = bool(st.session_state.get('dados_periodos'))
        if ok:
            _status.update(label="dados carregados", state="complete", expanded=False)
        else:
            _status.update(label="falha ao carregar dados", state="error", expanded=True)
    return ok

# Callbacks para navegação entre menus (evita conflito)
def _on_main_menu_change():
    """Callback quando menu principal é clicado."""
    sel = st.session_state.get('nav_main')
    if sel is not None and sel in MENU_PRINCIPAL:
        st.session_state['menu_atual'] = sel
        # Limpar seleção do menu secundário
        if 'nav_sec' in st.session_state:
            st.session_state['nav_sec'] = None

def _on_sec_menu_change():
    """Callback quando menu secundário é clicado."""
    sel = st.session_state.get('nav_sec')
    if sel is not None and sel in MENU_SECUNDARIO:
        st.session_state['menu_atual'] = sel
        # Limpar seleção do menu principal
        if 'nav_main' in st.session_state:
            st.session_state['nav_main'] = None

def _nav_para_menu(dest: str):
    """Callback de navegação direta: atualiza menu_atual sem st.rerun() explícito.

    Usado por botões de atalho (página Sobre, sidebar) para evitar double rerun:
    o callback roda antes do rerun que o próprio clique do botão já dispara.
    """
    st.session_state['menu_atual'] = dest
    if dest in MENU_PRINCIPAL:
        st.session_state['nav_main'] = dest
        st.session_state['nav_sec'] = None
    else:
        st.session_state['nav_sec'] = dest
        st.session_state['nav_main'] = None

def _recarregar_cache_callback():
    """Callback para o botão de recarga de cache: evita double rerun."""
    if forcar_recarregar_cache():
        st.toast("cache recarregado com sucesso!", icon="✅")
    else:
        st.toast("falha ao recarregar — arquivo não existe", icon="⚠️")

